cat > "$check_dir/tb.sv" <<'EOF'
\`timescale 1ns/1ps
module tb;
    reg clk = 0;
    reg rst_n = 1;
    reg a = 0;
    wire match;
    reg [8:0] history;
    reg expected;
    integer window;
    integer bit_index;
    TopModule dut(clk, rst_n, a, match);

    task reset;
        begin
            rst_n = 0;
            history = 0;
            expected = 0;
            #1;
            if (match !== 0) $fatal(1, "Asynchronous reset failed");
            rst_n = 1;
            #1;
        end
    endtask

    task sample(input reg value);
        begin
            a = value;
            #1;
            if (match !== expected) $fatal(1, "Match changed before clock edge");
            clk = 1;
            history = (history << 1) | value;
            expected = ((history & 9'b111000111) == 9'b011000110);
            #1;
            if (match !== expected) $fatal(1, "Unexpected match for %b", history);
            clk = 0;
            #1;
        end
    endtask

    initial begin
        for (window = 0; window < 512; window = window + 1) begin
            reset;
            for (bit_index = 8; bit_index >= 0; bit_index = bit_index - 1)
                sample(window[bit_index]);
        end
        reset;
        window = 12'b011011110110;
        for (bit_index = 11; bit_index >= 0; bit_index = bit_index - 1)
            sample(window[bit_index]);
        if (match !== 1) $fatal(1, "Overlapping match failed");
        reset;
        $display("PASS: all 512 windows, overlapping matches, and asynchronous reset");
        $finish;
    end
endmodule
EOF
iverilog -g2012 -s tb -o "$check_dir/sim" TopModule.sv "$check_dir/tb.sv"
vvp "$check_dir/sim"
